 "content": "def transform(grid):
    """Overlay the two marked regions on either side of a solid separator."""
    h, w = len(grid), len(grid[0])
    # A uniform nonzero line separates two aligned binary pictures.
    for r, row in enumerate(grid):
        if row[0] != 0 and all(x == row[0] for x in row):
            a, b = grid[:r], grid[r + 1:]
            if a and len(a) == len(b):
                return [[2 if a[i][j] != 0 and b[i][j] != 0 else 0
                         for j in range(w)] for i in range(len(a))]
    for c in range(w):
        if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h)):
            a = [row[:c] for row in grid]
            b = [row[c + 1:] for row in grid]
            if a and len(a[0]) == len(b[0]):
                return [[2 if a[i][j] != 0 and b[i][j] != 0 else 0
                         for j in range(len(a[0]))] for i in range(h)]
    raise ValueError("No aligned solid separator found")
